(5413448, 778264, 101256, '<td valign="top">Sharp, crisp and evocative.  I really like the overall tone and greenish color cast - makes for a very effective capture. Well done.</td>', 'Sharp, crisp and evocative.  I really like the overall tone and greenish color cast - makes for a very effective capture. Well done.', '2009-04-01 20:24:45.000000', NULL, 1),
(5413453, 776484, 101256, '<td valign="top">Poignant and very moody.  I can''t rate it as a 10 though because of DOF problems around the nose and chest - it would have been a great one if the details could have been kept in focus.</td>', 'Poignant and very moody.  I can''t rate it as a 10 though because of DOF problems around the nose and chest - it would have been a great one if the details could have been kept in focus.', '2009-04-01 20:27:11.000000', NULL, 1),
(5413458, 777378, 101256, '<td valign="top">Great image - a Mini Militia.  Very crisp, but I think this could have done with a little less foreground and a tighter capture on the boys with bokeh. Still a nice capture.</td>', 'Great image - a Mini Militia.  Very crisp, but I think this could have done with a little less foreground and a tighter capture on the boys with bokeh. Still a nice capture.', '2009-04-01 20:28:33.000000', NULL, 1),
(5413462, 775684, 101256, '<td valign="top">Has a video game cut story feel to it - probably the green lighting. In my opinion, the strong light behind the rifleman detracts from the central theme and give the image a feeling of false intensity.</td>', 'Has a video game cut story feel to it - probably the green lighting. In my opinion, the strong light behind the rifleman detracts from the central theme and give the image a feeling of false intensity.', '2009-04-01 20:30:08.000000', NULL, 1),
