(5413510, 777513, 98647, '<td valign="top">The depth of field is a little too shallow for me, and the focus isn''t quite on the eyes.</td>', 'The depth of field is a little too shallow for me, and the focus isn''t quite on the eyes.', '2009-04-01 20:55:01.000000', NULL, 1),
