(5419060, 777945, 103142, '<td valign="top">I didn''t mark the picture down because of it, but I found the inner frame to be very distracting. I like the photo, but I think it would be much stronger without the frame.</td>', 'I didn''t mark the picture down because of it, but I found the inner frame to be very distracting. I like the photo, but I think it would be much stronger without the frame.', '2009-04-04 22:43:47.000000', NULL, 1),
(5419141, 778385, 57447, '<td valign="top">I like this little cow.  And the dish ran away with the spoon.</td>', 'I like this little cow.  And the dish ran away with the spoon.', '2009-04-05 00:37:55.000000', NULL, 1),
(5419199, 778092, 7485, '<td valign="top">Over the top processing like this doesn''t work for me</td>', 'Over the top processing like this doesn''t work for me', '2009-04-05 01:27:59.000000', NULL, 1),
(5419201, 777751, 7485, '<td valign="top">I like the concept and well matched colors, but her startled expression is a bit odd, and</td>', 'I like the concept and well matched colors, but her startled expression is a bit odd, and', '2009-04-05 01:34:38.000000', NULL, 1),
(5419202, 777302, 7485, '<td valign="top">I''m not a fan of selective desaturation, but I have to admit that it works very well here. The contrast between her perfect skin and the lace is emphasized by the color. 8</td>', 'I''m not a fan of selective desaturation, but I have to admit that it works very well here. The contrast between her perfect skin and the lace is emphasized by the color. 8', '2009-04-05 01:37:30.000000', NULL, 1),
(5419205, 772864, 7485, '<td valign="top">Great idea, but the distorted greenish reflections of her eyes really freak me out</td>', 'Great idea, but the distorted greenish reflections of her eyes really freak me out', '2009-04-05 01:38:47.000000', NULL, 1),
(5419255, 778040, 66192, '<td valign="top">this reminds me of the shots in sports Illustrated by peter read miller</td>', 'this reminds me of the shots in sports Illustrated by peter read miller', '2009-04-05 04:34:32.000000', NULL, 1),
(5419320, 769805, 88718, '<td valign="top">Looks like a noisy image but nevertheless a striking composition</td>', 'Looks like a noisy image but nevertheless a striking composition', '2009-04-05 07:42:42.000000', NULL, 1),
