(5425464, 775062, 9462, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by jlanoue:</b></div><hr/><i> astrophotography is just the art of long exposure photography of a moving object </i></td></tr></table> <br/>Ahem... aren''t we the ones moving and not the object Mr Smarty-pants?</td>', 'Originally posted by jlanoue: astrophotography is just the art of long exposure photography of a moving object  Ahem... aren''t we the ones moving and not the object Mr Smarty-pants?', '2009-04-08 01:58:45.000000', NULL, 0),
(5425482, 778157, 39430, '<td valign="top">Beautiful shot - and we all know that being in the right place at the right time is seldom luck.  It takes planning and dedication to get to an amazing place like this at the right time.  :)</td>', 'Beautiful shot - and we all know that being in the right place at the right time is seldom luck.  It takes planning and dedication to get to an amazing place like this at the right time.  :)', '2009-04-08 02:03:17.000000', NULL, 0),
